static int remove_adv_monitor(struct sock *sk, struct hci_dev *hdev,
			      void *data, u16 len)
{
	struct mgmt_pending_cmd *cmd;
	struct mgmt_cp_remove_adv_monitor *cp = data;
	struct remove_adv_monitor_data *sync_data;
	int err, status;

	hci_dev_lock(hdev);

	if (pending_find(MGMT_OP_SET_LE, hdev) ||
	    pending_find(MGMT_OP_REMOVE_ADV_MONITOR, hdev) ||
	    pending_find(MGMT_OP_ADD_ADV_PATTERNS_MONITOR, hdev) ||
	    pending_find(MGMT_OP_ADD_ADV_PATTERNS_MONITOR_RSSI, hdev)) {
		status = MGMT_STATUS_BUSY;
		goto unlock;
	}

	sync_data = kmalloc(sizeof(*sync_data), GFP_KERNEL);
	if (!sync_data) {
		status = MGMT_STATUS_NO_RESOURCES;
		goto unlock;
	}

	sync_data->handle = __le16_to_cpu(cp->monitor_handle);

	cmd = mgmt_pending_add(sk, MGMT_OP_REMOVE_ADV_MONITOR, hdev, data, len);
	if (!cmd) {
		status = MGMT_STATUS_NO_RESOURCES;
		goto free_sync_data;
	}

	err = hci_cmd_sync_submit(hdev, mgmt_remove_adv_monitor_sync, sync_data,
				  mgmt_remove_adv_monitor_complete);

	if (err) {
		mgmt_pending_remove(cmd);

		if (err == -ENOMEM)
			status = MGMT_STATUS_NO_RESOURCES;
		else
			status = MGMT_STATUS_FAILED;

		goto free_sync_data;
	}

	hci_dev_unlock(hdev);

	return 0;

free_sync_data:
	kfree(sync_data);
unlock:
	hci_dev_unlock(hdev);
	return mgmt_cmd_status(sk, hdev->id, MGMT_OP_REMOVE_ADV_MONITOR,
			       status);
}

